import { createServer } from "node:http";
import { spawn } from "node:child_process";
import { existsSync, readFileSync, mkdirSync, writeFileSync, statSync } from "node:fs";
import { join, extname } from "node:path";

const DIST = "/home/timidan/Desktop/resurgo-web/web/dist";
const QUEUE = "/tmp/claude-1000/-home-timidan/queue";
const OUT = "/tmp/claude-1000/-home-timidan-Desktop-resurgo-web/84dc7f6d-6177-43d4-a62b-8f8e40519bac/scratchpad/shots";
mkdirSync(OUT, { recursive: true });
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".svg": "image/svg+xml", ".png": "image/png", ".webp": "image/webp", ".woff2": "font/woff2", ".woff": "font/woff", ".json": "application/json" };

const server = createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  const m = url.pathname.match(/^\/api\/installations\/(\d{1,12})$/);
  if (m) {
    const status = join(QUEUE, "status", `${m[1]}.json`);
    const reqf = join(QUEUE, "requests", `${m[1]}.json`);
    res.setHeader("content-type", "application/json");
    if (existsSync(status)) return res.end(readFileSync(status));
    if (existsSync(reqf)) return res.end(JSON.stringify({ installation_id: Number(m[1]), state: "received" }));
    res.statusCode = 404;
    return res.end('{"detail":"no such installation"}');
  }
  if (url.pathname.startsWith("/api/")) {
    const r = await fetch("http://REDACTED:8787" + req.url);
    res.statusCode = r.status;
    res.setHeader("content-type", r.headers.get("content-type") ?? "application/json");
    return res.end(Buffer.from(await r.arrayBuffer()));
  }
  let f = join(DIST, url.pathname);
  if (!f.startsWith(DIST) || !existsSync(f) || !statSync(f).isFile()) f = join(DIST, "index.html");
  res.setHeader("content-type", types[extname(f)] ?? "application/octet-stream");
  res.end(readFileSync(f));
});
