let n = 0;
const waiting = new Map();
ws.onmessage = (m) => { const d = JSON.parse(m.data); waiting.get(d.id)?.(d); };
const send = (method, params = {}) => new Promise((res) => { waiting.set(++n, res); ws.send(JSON.stringify({ id: n, method, params })); });
const val = async (e) => (await send("Runtime.evaluate", { expression: e, returnByValue: true })).result.result.value;

async function shot(path, selector, name, width, theme, pad = 16) {
  await send("Emulation.setDeviceMetricsOverride", { width, height: 900, deviceScaleFactor: 2, mobile: false });
  await send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-color-scheme", value: theme }] });
  await send("Page.navigate", { url: "http://REDACTED:8788" + path });
  await sleep(3500);
  const box = JSON.parse(await val(`(() => { const e = document.querySelector(${JSON.stringify(selector)}); e.scrollIntoView({block:'center'});
    const r = e.getBoundingClientRect(); return JSON.stringify({ x: r.left + scrollX, y: r.top + scrollY, w: r.width, h: r.height }); })()`));
  await sleep(1200);
  const bg = await val("getComputedStyle(document.body).backgroundColor");
  const r = await send("Page.captureScreenshot", { format: "png", captureBeyondViewport: true, clip: { x: Math.max(0, box.x - pad), y: Math.max(0, box.y - pad), width: Math.min(width, box.w + pad * 2), height: box.h + pad * 2, scale: 1 } });
  const f = `${OUT}/${name}-${width}-${theme}.png`;
  writeFileSync(f, Buffer.from(r.result.data, "base64"));
  console.log(f, "bg", bg);
}

